"""
FWMIS Loadform Builder
Drop in the Wildlife Sweep & Feature Tracker, download a ready-to-submit
FWMIS loadform. Each feature uses its Lat, Long cell; if blank, the row's
ATS Start/End is used. The project description is written from the tracker's
FWMIS Info sheet. The official FWMIS template is built into this file, so
nothing else is needed. Only the data cells of the template are changed;
every sheet, dropdown, comment, hidden column and style stays as AEP ships it.

Run:  streamlit run fwmis_loadform_app.py
"""

import io
import re
import json
import base64
import zipfile
