def q(tag):
    return f"{{{NS}}}{tag}"


# ----------------------------------------------------------------------------
# Low level xlsx editing
# ----------------------------------------------------------------------------
def col_to_idx(col):
    n = 0
    for ch in col:
        n = n * 26 + (ord(ch) - 64)
    return n


def split_ref(ref):
    m = re.match(r"([A-Z]+)(\d+)$", ref)
    return m.group(1), int(m.group(2))


def excel_serial(d):
    return (d - dt.date(1899, 12, 30)).days


class SharedStrings:
    def __init__(self, xml_bytes):
        self.root = etree.fromstring(xml_bytes)
        self.items = self.root.findall(q("si"))
        self.index = {}
        for i, si in enumerate(self.items):
            t = si.find(q("t"))
            if t is not None and len(si) == 1:
                self.index.setdefault(t.text or "", i)
        self.count = len(self.items)
        self.refs_added = 0

    def get(self, text):
        self.refs_added += 1
        if text in self.index:
            return self.index[text]
        si = etree.Element(q("si"))
        t = etree.SubElement(si, q("t"))
        t.text = text
        if text != text.strip() or "\n" in text:
            t.set("{http://www.w3.org/XML/1998/namespace}space", "preserve")
        if self.items:
            self.items[-1].addnext(si)
        else:
            self.root.insert(0, si)
        self.items.append(si)
        self.index[text] = self.count
        self.count += 1
        return self.count - 1

    def to_bytes(self):
        self.root.set("uniqueCount", str(self.count))
        self.root.set("count", str(int(self.root.get("count", "0")) + self.refs_added))
        return etree.tostring(self.root, xml_declaration=True, encoding="UTF-8", standalone=True)


class SheetXml:
    def __init__(self, xml_bytes):
        self.root = etree.fromstring(xml_bytes)
        self.data = self.root.find(q("sheetData"))
        self.rows = {int(r.get("r")): r for r in self.data.findall(q("row"))}
        self.col_style = {}
        cols = self.root.find(q("cols"))
        if cols is not None:
            for c in cols.findall(q("col")):
                if c.get("style"):
                    for i in range(int(c.get("min")), int(c.get("max")) + 1):
                        self.col_style[i] = c.get("style")

    def clear_values_from(self, first_row):
        for rn, row in self.rows.items():
            if rn >= first_row:
                for c in row.findall(q("c")):
                    for child in list(c):
                        c.remove(child)
                    c.attrib.pop("t", None)

    def _row(self, rn):
        if rn in self.rows:
            row = self.rows[rn]
        else:
            row = etree.Element(q("row"))
            row.set("r", str(rn))
            later = [r for r in self.rows if r > rn]
            if later:
                self.rows[min(later)].addprevious(row)
            else:
                self.data.append(row)
            self.rows[rn] = row
        row.attrib.pop("spans", None)
        return row

    def _cell(self, ref, style):
        col, rn = split_ref(ref)
        ci = col_to_idx(col)
        row = self._row(rn)
        target = None
        for c in row.findall(q("c")):
            k = col_to_idx(split_ref(c.get("r"))[0])
            if k == ci:
                target = c
                break
            if k > ci:
                target = etree.Element(q("c"))
                target.set("r", ref)
                c.addprevious(target)
                break
        if target is None:
            target = etree.SubElement(row, q("c"))
            target.set("r", ref)
        if style is not None:
            target.set("s", str(style))
        elif "s" not in target.attrib and ci in self.col_style:
            target.set("s", self.col_style[ci])
        return target

    def set(self, ref, value, sst, style=None):
        if value is None or (isinstance(value, str) and value.strip() == ""):
            return
        c = self._cell(ref, style)
        for child in list(c):
            c.remove(child)
        c.attrib.pop("t", None)
        v = etree.SubElement(c, q("v"))
        if isinstance(value, (int, float)):
            v.text = repr(float(value)) if isinstance(value, float) else str(value)
        else:
            c.set("t", "s")
            v.text = str(sst.get(str(value)))

    def to_bytes(self):
        dim = self.root.find(q("dimension"))
        if dim is not None:
            m = re.match(r"(?:[A-Z]+\d+:)?([A-Z]+)\d+$", dim.get("ref", "A1"))
            last_col = m.group(1) if m else "A"
            dim.set("ref", f"A1:{last_col}{max(self.rows) if self.rows else 1}")
        return etree.tostring(self.root, xml_declaration=True, encoding="UTF-8", standalone=True)


def sheet_paths(zf):
    wb = StdET.fromstring(zf.read("xl/workbook.xml"))
    rels = StdET.fromstring(zf.read("xl/_rels/workbook.xml.rels"))
    rid_target = {r.get("Id"): r.get("Target") for r in rels.findall(f"{{{NS_PKG_REL}}}Relationship")}
    out = {}
    for s in wb.find(f"{{{NS}}}sheets"):
        target = rid_target[s.get(f"{{{NS_REL}}}id")].lstrip("/")
        out[s.get("name")] = target if target.startswith("xl/") else "xl/" + target
    return out


def build_loadform(template_bytes, project, survey, rows):
    zin = zipfile.ZipFile(io.BytesIO(template_bytes))
    paths = sheet_paths(zin)
    sst = SharedStrings(zin.read("xl/sharedStrings.xml"))

    proj = SheetXml(zin.read(paths[PROJECT_SHEET]))
    proj.clear_values_from(FIRST_DATA_ROW)
    for key, (col, style) in PROJECT_CELLS.items():
        proj.set(f"{col}{FIRST_DATA_ROW}", project.get(key), sst, style)

    surv = SheetXml(zin.read(paths[SURVEY_SHEET]))
    surv.clear_values_from(FIRST_DATA_ROW)
    for i, r in enumerate(rows):
        values = {
            "survey_type": survey["survey_type"],
            "start": excel_serial(survey["start"]),
            "end": excel_serial(survey["end"]),
            "sensitive": survey["sensitive"],
            "loc_type": r["loc_type"],
            "gis_source": survey["gis_source"],
            "datum": survey["datum"],
            "in_alberta": "Y",
            "lat": round(float(r["lat"]), 6) if r.get("lat") is not None else None,
            "lon": round(float(r["lon"]), 6) if r.get("lon") is not None else None,
            "loc_comments": r.get("loc_comments"),
            "feature": r["feature"],
            "obs_date": excel_serial(r["date"]),
            "confidence": survey["confidence"],
            "species": r["species"],
            "comments": r["comment"],
        }
        for prefix, ats in (("s_", r.get("ats_start")), ("e_", r.get("ats_end"))):
            ats = ats or {}
            values.update({prefix + "lsd": ats.get("lsd"), prefix + "quarter": ats.get("quarter"),
                           prefix + "section": ats.get("section"), prefix + "township": ats.get("township"),
                           prefix + "range": ats.get("range"), prefix + "meridian": ats.get("meridian")})
        for key, (col, style) in SURVEY_COLS.items():
            surv.set(f"{col}{FIRST_DATA_ROW + i}", values[key], sst, style)

    changed = {
        paths[PROJECT_SHEET]: proj.to_bytes(),
        paths[SURVEY_SHEET]: surv.to_bytes(),
        "xl/sharedStrings.xml": sst.to_bytes(),
    }
    out = io.BytesIO()
    with zipfile.ZipFile(out, "w") as zout:
        for info in zin.infolist():
            zi = zipfile.ZipInfo(info.filename, date_time=info.date_time)
            zi.compress_type = info.compress_type
            zi.external_attr = info.external_attr
            zout.writestr(zi, changed.get(info.filename, zin.read(info.filename)))
    return out.getvalue()


# ----------------------------------------------------------------------------
# FWMIS code lists and matching
# ----------------------------------------------------------------------------
@st.cache_data(show_spinner=False)
def read_code_lists(template_bytes):
    wb = load_workbook(io.BytesIO(template_bytes), read_only=True, data_only=True)
    rows = list(wb[CODES_SHEET].iter_rows(values_only=True))
    header = rows[0]
    lists = {}
    for name in ["tax_TAXONOMIC", "inv_SURVEYTYPE", "inv_SITFEATURE", "inv_CONFDNTLVL",
                 "inv_LOCTYPE", "inv_GISSOURCE", "inv_GISDATUM", "inv_ATSQUARTER", "inv_ATSMERIDIA"]:
        idx = header.index(name)
        lists[name] = list(dict.fromkeys(r[idx] for r in rows[1:] if idx < len(r) and r[idx]))
    wb.close()
    return lists


def norm(text):
    return re.sub(r"\s+", " ", str(text).upper().replace("–", "-").strip())


def code_of(option):
    return option.rsplit(" -", 1)[-1].strip()


def name_of(option):
    return option.rsplit(" -", 1)[0].strip()


def pick_option(options, value):
    """Find an option by full text, code or name."""
    if value is None or str(value).strip() == "":
        return None
    n = norm(value)
    for o in options:
        if n in (norm(o), norm(code_of(o)), norm(name_of(o))):
            return o
    return None


def auto_species(name, options):
    if not name:
        return None
    by_code = {code_of(o): o for o in options}
    by_name = {norm(name_of(o)): o for o in options}
    n = norm(name)
    n = re.sub(r"\b(SPP|SP)\b\.?", "", n).replace(".", "").strip()
    n = re.sub(r"\s+", " ", n)
    if n in by_name:
        return by_name[n]
    if n in SPECIES_ALIASES and SPECIES_ALIASES[n] in by_code:
        return by_code[SPECIES_ALIASES[n]]
    if n.endswith("S") and n[:-1] in SPECIES_ALIASES and SPECIES_ALIASES[n[:-1]] in by_code:
        return by_code[SPECIES_ALIASES[n[:-1]]]
    if n + "S" in by_name:
        return by_name[n + "S"]
    return None


def auto_feature(text, options):
    by_code = {code_of(o): o for o in options}
    t = str(text or "").lower()
    for code, words in FEATURE_RULES:
        if any(re.search(r"\b" + re.escape(w), t) for w in words):
            return by_code.get(code)
    return by_code.get("OTHR")


def load_saved_maps():
    try:
        data = json.loads(MAP_FILE.read_text(encoding="utf-8"))
        return data.get("species", {}), data.get("features", {})
    except Exception:
        return {}, {}


def save_maps(species_map, feature_map):
    try:
        MAP_FILE.write_text(json.dumps({"species": species_map, "features": feature_map},
                                       indent=2, sort_keys=True), encoding="utf-8")
        return True
    except Exception:
        return False


# ----------------------------------------------------------------------------
# ATS legal land locations and KPs
# ----------------------------------------------------------------------------
ATS_RE = re.compile(r"^\s*(?:(NE|NW|SE|SW)|(?:LSD\s*)?(\d{1,2}))\s*-\s*(\d{1,2})\s*-\s*(\d{1,3})\s*-\s*(\d{1,2})"
                    r"\s*-?\s*W\s*([4-6])\s*M?\s*$", re.I)


def parse_ats(text):
    """'NE-16-75-10-W6M' or '12-16-75-10-W6M' -> dict, else None."""
    m = ATS_RE.match(str(text or ""))
    if not m:
        return None
    quarter, lsd, sec, twp, rge, mer = m.groups()
    sec, twp, rge, mer = int(sec), int(twp), int(rge), int(mer)
    if not (1 <= sec <= 36 and 1 <= twp <= 126 and 1 <= rge <= 30):
        return None
    if lsd and not (1 <= int(lsd) <= 16):
        return None
    return {"quarter": quarter.upper() if quarter else None, "lsd": int(lsd) if lsd else None,
            "section": sec, "township": twp, "range": rge, "meridian": mer}


def ats_to_fwmis(ats, lists):
    if not ats:
        return None
    out = dict(ats)
    out["quarter"] = pick_option(lists["inv_ATSQUARTER"], ats["quarter"]) if ats["quarter"] else None
    out["meridian"] = pick_option(lists["inv_ATSMERIDIA"], str(ats["meridian"]))
    return out


def parse_kp(text):
    """'KP 20+100' -> 20.1. Returns None when there is not exactly one KP."""
    hits = re.findall(r"KP\s*(\d+)\s*\+\s*(\d+)", str(text or ""), re.I)
    if len(hits) != 1:
        return None
    km, m = hits[0]
    return int(km) + int(m) / 1000


def project_extent(df):
    """Legal location at the lowest and highest KP in the tracker."""
    pts = []
    for _, r in df.iterrows():
        for kp, ats in ((r["kp_start"], r["ats_start_text"]), (r["kp_end"], r["ats_end_text"])):
            k = parse_kp(kp)
            if k is not None and parse_ats(ats):
                pts.append((k, ats.strip()))
    if pts:
        return min(pts)[1], max(pts)[1]
    starts = [a for a in df["ats_start_text"] if parse_ats(a)]
    ends = [a for a in df["ats_end_text"] if parse_ats(a)]
    return (starts[0] if starts else ""), (ends[-1] if ends else "")


def write_description(client, short, work, scope, start, end):
    work = (work or "wildlife sweep").strip()
    short = (short or "").strip()
    return DESCRIPTION_TEMPLATE.format(
        client=(client or "").strip(),
        short=f" ({short})" if short and short != (client or "").strip() else "",
        article="an" if work[:1].lower() in "aeiou" else "a",
        work=work, scope=(scope or "").strip().rstrip("."), start=start or "", end=end or "")


# ----------------------------------------------------------------------------
# Tracker reading
# ----------------------------------------------------------------------------
def to_date(v):
    if v is None or (isinstance(v, float) and pd.isna(v)) or v == "":
        return None
    if isinstance(v, dt.datetime):
        return v.date()
    if isinstance(v, dt.date):
        return v
    d = pd.to_datetime(v, errors="coerce")
    return None if pd.isna(d) else d.date()


def to_num(v):
    try:
        return float(str(v).strip())
    except (TypeError, ValueError):
        return None


def parse_latlon(text):
    """'55.123456, -119.123456' -> (55.123456, -119.123456). Fixes swapped order and a missing minus."""
    nums = re.findall(r"-?\d+(?:\.\d+)?", str(text or ""))
    if len(nums) != 2:
        return None
    a, b = float(nums[0]), float(nums[1])
    if abs(a) > abs(b):  # entered as long, lat
        a, b = b, a
    if b > 0:
        b = -b
    return a, b


def read_tracker(file_bytes):
    wb = load_workbook(io.BytesIO(file_bytes), data_only=True)
    ws = wb[TRACKER_SHEET] if TRACKER_SHEET in wb.sheetnames else wb.worksheets[0]

    header_row, cols = None, {}
    for r in range(1, 11):
        labels = {norm(ws.cell(r, c).value).lower(): c for c in range(1, ws.max_column + 1) if ws.cell(r, c).value}
        if "common name" in labels or "species" in labels:
            header_row = r
            for key, names in TRACKER_HEADERS.items():
                cols[key] = next((labels[n] for n in names if n in labels), None)
            break
    if header_row is None:
        raise ValueError("Could not find the tracker header row (looking for a 'Common Name' column).")
    if cols["species"] is None or cols["observation"] is None:
        raise ValueError("Tracker needs 'Incidental Observations' and 'Common Name' columns.")

    recs = []
    for r in range(header_row + 1, ws.max_row + 1):
        get = lambda k: ws.cell(r, cols[k]).value if cols.get(k) else None
        species, obs = get("species"), get("observation")
        if not species and not obs:
            continue
        if not species and len(str(obs)) > 80:  # footer note
            continue
        lat, lon = to_num(get("lat")), to_num(get("lon"))
        ll_text = str(get("latlon") or "").strip()
        if ll_text:
            parsed = parse_latlon(ll_text)
            lat, lon = parsed if parsed else (None, None)
        recs.append({
            "row": r,
            "latlon_text": ll_text,
            "species_name": str(species).strip() if species else "",
            "observation": str(obs).strip() if obs else "",
            "date": to_date(get("obs_date")) or to_date(get("sweep_date")),
            "sweep_date": to_date(get("sweep_date")),
            "lat": lat,
            "lon": lon,
            "status": str(get("status")).strip() if get("status") else "",
            "kp_start": str(get("kp_start") or "").strip(),
            "kp_end": str(get("kp_end") or "").strip(),
            "ats_start_text": str(get("ats_start") or "").strip(),
            "ats_end_text": str(get("ats_end") or "").strip(),
        })

    info = {}
    if INFO_SHEET in wb.sheetnames:
        wi = wb[INFO_SHEET]
        for r in range(1, wi.max_row + 1):
            k, v = wi.cell(r, 1).value, wi.cell(r, 2).value
            if k:
                info[norm(k)] = v
    title = ws.cell(1, 1).value if header_row > 1 else None
    wb.close()
    return pd.DataFrame(recs), info, {"has_latlon": bool(cols["latlon"] or (cols["lat"] and cols["lon"])), "title": title}


def info_get(info, *keys, default=None):
    for k in keys:
        v = info.get(norm(k))
        if v not in (None, ""):
            return v
    return default


